{
  "protocol": "focus-trace-v3-reader-response-v1",
  "reader_id": "reader_29_38_sol",
  "focus_ref": "29:38",
  "trace_kind": "reconstructed",
  "baseline_models": [
    {
      "model_id": "B01_salience_without_blindness",
      "confidence": "strong",
      "focus_anchor": "زَيَّنَ لَهُمُ الشَّيْطَانُ أَعْمَالَهُمْ فَصَدَّهُمْ عَنِ السَّبِيلِ وَكَانُوا مُسْتَبْصِرِينَ",
      "mechanism": "Beautification alters the valuation of purposive deeds, and those positively recoded deeds become the means of diversion from an available route. Since the people retain inward discernment, the failure lies between recognition and action-selection rather than in missing evidence.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r04",
          "branch_key": "root_000660/B002",
          "role": "Making an object's attractiveness salient supplies the operation that recodes the deeds as desirable."
        },
        {
          "occurrence_id": "29:38/r06",
          "branch_key": "root_001046/B001",
          "role": "Deliberate action supplies both the object of recoding and the behavior through which diversion is enacted."
        },
        {
          "occurrence_id": "29:38/r05",
          "branch_key": "root_000796/B004",
          "role": "The image of a defiant adversary supplies an intentional selector of appearances rather than an innocent aesthetic response."
        },
        {
          "occurrence_id": "29:38/r07",
          "branch_key": "root_000848/B001",
          "role": "Turning or holding another away supplies the causal rerouting from attractive action to missed route."
        },
        {
          "occurrence_id": "29:38/r08",
          "branch_key": "root_000672/B001",
          "role": "A route that can actually be traveled supplies the normative direction from which they are displaced."
        },
        {
          "occurrence_id": "29:38/r10",
          "branch_key": "root_000121/B002",
          "role": "Penetrating inward discernment supplies retained cognition, making the failure one of governance rather than perception."
        }
      ],
      "changed_reading": {
        "before": "They missed the path because Satan made them unable to see it.",
        "after": "They could discern, yet their action-selection was captured: their own attractive deeds carried the diversion."
      }
    },
    {
      "model_id": "B02_ruins_as_medium",
      "confidence": "strong",
      "focus_anchor": "وَقَد تَبَيَّنَ لَكُم مِّن مَّسَاكِنِهِمْ",
      "mechanism": "Disclosure issues from the dwellings themselves. Settled places function as a persistent material record through which a later audience apprehends an absent community, contrasting retrospective clarity with the residents' unused insight.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r02",
          "branch_key": "root_000170/B004",
          "role": "Emergence into clarity supplies the evidentiary result produced by inspecting the site."
        },
        {
          "occurrence_id": "29:38/r03",
          "branch_key": "root_000726/B002",
          "role": "An inhabited home supplies the concrete medium from which historical disclosure arises."
        },
        {
          "occurrence_id": "29:38/r03",
          "branch_key": "root_000726/B009",
          "role": "A fixed place of settlement supplies the persistence needed for a location to retain evidence."
        },
        {
          "occurrence_id": "29:38/r10",
          "branch_key": "root_000121/B001",
          "role": "Actual seeing supplies the verse's contrast between what later observers can inspect and what earlier residents failed to use."
        }
      ],
      "changed_reading": {
        "before": "The dwellings merely locate a story that has become known.",
        "after": "The dwellings are an evidence-producing archive: place itself discloses the consequence of misdirected action."
      }
    },
    {
      "model_id": "B03_habitable_barrier",
      "confidence": "medium",
      "focus_anchor": "مَسَاكِنِهِمْ ... أَعْمَالَهُمْ فَصَدَّهُمْ عَنِ السَّبِيلِ",
      "mechanism": "What gives psychic rest and local stability can be made attractive until intentional practices form an inhabitable normality. The distance image attached to the adversary and the barrier image attached to obstruction permit a systemic reading: comfortable normality itself can hold a population away from the route.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r03",
          "branch_key": "root_000726/B004",
          "role": "A beloved source of repose supplies the affective attachment that makes a settled order difficult to leave."
        },
        {
          "occurrence_id": "29:38/r04",
          "branch_key": "root_000660/B002",
          "role": "Displayed attractiveness supplies the reinforcement that normalizes the attached practices."
        },
        {
          "occurrence_id": "29:38/r06",
          "branch_key": "root_001046/B001",
          "role": "Purposive deeds supply the repeated components from which the normality is built."
        },
        {
          "occurrence_id": "29:38/r05",
          "branch_key": "root_000796/B001",
          "role": "The lexical image of remoteness supplies the spatial outcome produced by the adversarial process."
        },
        {
          "occurrence_id": "29:38/r07",
          "branch_key": "root_000848/B005",
          "role": "A massive natural obstruction supplies the image of practices hardening into a structural barrier."
        },
        {
          "occurrence_id": "29:38/r08",
          "branch_key": "root_000672/B001",
          "role": "The traversable road supplies the excluded alternative outside the comfortable system."
        }
      ],
      "changed_reading": {
        "before": "Satan momentarily distracts people from an otherwise unobstructed road.",
        "after": "Beautified practice can become a comfortable social habitat whose apparent stability is itself the roadblock."
      }
    },
    {
      "model_id": "B04_work_becomes_track",
      "confidence": "exploratory",
      "focus_anchor": "أَعْمَالَهُمْ فَصَدَّهُمْ عَنِ السَّبِيلِ",
      "mechanism": "A peripheral branch of ع م ل images a well-used road, allowing deeds and path to enter direct competition. Repeated action lays down a familiar track, beautification increases traffic on it, and that traveled familiarity becomes the operative turning-away.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r06",
          "branch_key": "root_001046/B011",
          "role": "A road worn into usability supplies the material analogy by which accumulated deeds become a rival track."
        },
        {
          "occurrence_id": "29:38/r04",
          "branch_key": "root_000660/B002",
          "role": "Heightened attractiveness supplies the feedback that draws further movement along the familiar track."
        },
        {
          "occurrence_id": "29:38/r07",
          "branch_key": "root_000848/B001",
          "role": "Active diversion supplies the displacement caused by continued use of the rival track."
        },
        {
          "occurrence_id": "29:38/r08",
          "branch_key": "root_000672/B001",
          "role": "The intended road supplies the route with which the deed-made track competes."
        }
      ],
      "changed_reading": {
        "before": "Their deeds and the path are separate objects in the sentence.",
        "after": "Their deeds can be imaged as laying a rival path; walking what they repeatedly made attractive is itself the diversion."
      }
    }
  ],
  "context_deltas": [
    {
      "model_id": "D01_assayed_finish",
      "status": "revised",
      "confidence": "medium",
      "mechanism": "The opening testing sequence treats profession and action like material placed under assay. A later peripheral image of coating metal supplies a further analogy: satanic beautification is a finish under which defective action can pass visual inspection, while pressure tests the substrate.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r04",
          "branch_key": "root_000660/B002",
          "role": "Applied attractiveness supplies the deceptive surface whose relation to underlying quality is being tested."
        },
        {
          "occurrence_id": "29:38/r06",
          "branch_key": "root_001046/B001",
          "role": "Intentional conduct supplies the underlying material whose quality matters beyond its finish."
        },
        {
          "occurrence_id": "29:2/r06",
          "branch_key": "root_001128/B001",
          "role": "An assay applied to metal or persons supplies the diagnostic pressure that distinguishes surface appearance from composition."
        },
        {
          "occurrence_id": "29:3/r05",
          "branch_key": "root_000852/B004",
          "role": "Truth realized in deed supplies a performance criterion stronger than verbal or visual presentation."
        },
        {
          "occurrence_id": "29:63/r04",
          "branch_key": "root_001458/B005",
          "role": "The remote image of giving base material a precious metallic skin supplies the thin-coating analogy without redefining the contextual rainwater."
        }
      ],
      "structural_cues": [
        "29:2-4 move from professed belief through testing to truthful or evil action.",
        "The later water occurrence reactivates a materially remote coating image, permitting an assay-versus-finish revisit."
      ],
      "reader_inference": "Packet: adornment, purposive work, testing-as-assay, enacted truth, and a peripheral metallic-coating image. Inference: cosmetic finish can cause a false pass until trial exposes the substrate. Alternative: fitna may be only general ordeal and the water is plainly rain, so the coating remains a qualified material analogy.",
      "changed_reading": {
        "before": "Beautification simply causes a mistaken visual judgment.",
        "after": "Beautification functions like a finish over conduct; trial asks whether insight reaches beneath that finish and governs action."
      }
    },
    {
      "model_id": "D02_social_route_brokerage",
      "status": "new",
      "confidence": "strong",
      "mechanism": "A rival path is marketed with a false liability guarantee; later, shared devotion supplies affection before collapsing into mutual repudiation. Beautification can therefore be socially manufactured: belonging makes the route attractive, and promised transfer of guilt lowers its perceived cost.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r04",
          "branch_key": "root_000660/B002",
          "role": "The production of attractiveness supplies the persuasive layer placed over a collective route."
        },
        {
          "occurrence_id": "29:38/r08",
          "branch_key": "root_000672/B001",
          "role": "A route of access supplies the contested object that a group can rename and market as its own."
        },
        {
          "occurrence_id": "29:12/r04",
          "branch_key": "root_000175/B001",
          "role": "Following behind another supplies the recruitment relation by which people enter the offered route."
        },
        {
          "occurrence_id": "29:12/r05",
          "branch_key": "root_000672/B001",
          "role": "The explicitly possessive rival road supplies concrete evidence that diversion may substitute one route for another."
        },
        {
          "occurrence_id": "29:12/r06",
          "branch_key": "root_000357/B004",
          "role": "A guarantor's undertaking supplies the false promise that another party can absorb the recruit's liability."
        },
        {
          "occurrence_id": "29:13/r01",
          "branch_key": "root_000357/B003",
          "role": "Bearing moral weight supplies the eventual rebound and multiplication of the liability that was supposedly outsourced."
        },
        {
          "occurrence_id": "29:25/r06",
          "branch_key": "root_001634/B001",
          "role": "Interpersonal affection supplies the social adhesive that makes a shared false practice feel valuable."
        },
        {
          "occurrence_id": "29:25/r07",
          "branch_key": "root_000170/B003",
          "role": "A bond joining parties supplies the relational infrastructure through which the attraction circulates."
        },
        {
          "occurrence_id": "29:25/r14",
          "branch_key": "root_001359/B001",
          "role": "Hostile expulsion supplies the later reversal that reveals the supposed bond's instability."
        }
      ],
      "structural_cues": [
        "29:12 couples “follow our path” with “we will carry your errors,” then immediately denies the guarantee.",
        "29:25 moves from affection among the group to reciprocal repudiation and cursing."
      ],
      "reader_inference": "Packet: a rival route, following, a false guarantee, accumulated burdens, affection, and later expulsion. Inference: social attachment plus apparent liability transfer causes adoption of the beautified route. Alternative: these may be separate warnings rather than a specification of the focus's satanic mechanism.",
      "changed_reading": {
        "before": "Satanic beautification is a private misperception inside each individual.",
        "after": "It can operate as social and quasi-legal route brokerage: belonging beautifies the practice while false guarantees conceal its cost."
      }
    },
    {
      "model_id": "D03_migration_and_rehousing",
      "status": "new",
      "confidence": "medium",
      "mechanism": "Migration interrupts the repose implied by dwellings; the wide earth converts a blocked route into spatial choice, while the righteous are later placed in enduring garden chambers. Residence is thus morally dynamic: familiar shelter can stabilize captured valuation, whereas reoriented work leads to a different habitation.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r03",
          "branch_key": "root_000726/B004",
          "role": "A place or beloved object that quiets the self supplies the attachment from which departure may be costly."
        },
        {
          "occurrence_id": "29:38/r08",
          "branch_key": "root_000672/B001",
          "role": "The open route supplies movement as the alternative to remaining enclosed by familiar practice."
        },
        {
          "occurrence_id": "29:26/r03",
          "branch_key": "root_001578/B002",
          "role": "Leaving one abode for another supplies deliberate spatial rupture as a response to a captured environment."
        },
        {
          "occurrence_id": "29:56/r04",
          "branch_key": "root_001647/B001",
          "role": "Expansive room supplies the newly available field in which exclusive worship need not remain spatially trapped."
        },
        {
          "occurrence_id": "29:56/r03",
          "branch_key": "root_000025/B001",
          "role": "The broad terrestrial domain supplies a real alternative beyond the local dwelling."
        },
        {
          "occurrence_id": "29:58/r02",
          "branch_key": "root_001046/B001",
          "role": "Righteous intentional work supplies the reoriented conduct preceding a new placement."
        },
        {
          "occurrence_id": "29:58/r04",
          "branch_key": "root_000161/B001",
          "role": "Being assigned a settled abode supplies the positive counterpart to the ruined dwellings in the focus."
        },
        {
          "occurrence_id": "29:58/r06",
          "branch_key": "root_001079/B002",
          "role": "Elevated rooms supply a materially different architecture of secure residence."
        },
        {
          "occurrence_id": "29:58/r10",
          "branch_key": "root_000429/B001",
          "role": "Residence resistant to decay supplies the durability absent from the focus's evidentiary ruins."
        }
      ],
      "structural_cues": [
        "29:26 announces departure from one land toward the Lord.",
        "29:56 joins a wide earth to exclusive worship.",
        "29:58 joins righteous work to divine re-housing in enduring chambers."
      ],
      "reader_inference": "Packet: comforting habitation, migration, spatial wideness, righteous work, and durable re-housing. Inference: attachment to a beautified local order can help block exit, while departure reopens orientation and leads to another abode. Alternative: the focus's dwellings may be evidence only, not a causal attachment.",
      "changed_reading": {
        "before": "The ruined dwellings are only the endpoint of past deviation.",
        "after": "Dwelling becomes part of the route mechanism: one habitation can stabilize deviation, leaving can reopen the path, and reoriented work culminates in re-housing."
      }
    },
    {
      "model_id": "D04_diverted_become_blockers",
      "status": "revised",
      "confidence": "strong",
      "mechanism": "Another community's listed deeds include cutting the road in its public gathering. This activates a recursive reading of the focus: people diverted through beautified deeds can themselves embody and reproduce the obstruction, so satanic causation is implemented through human practice.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r06",
          "branch_key": "root_001046/B001",
          "role": "Purposive conduct supplies the human implementation layer of the obstructing process."
        },
        {
          "occurrence_id": "29:38/r07",
          "branch_key": "root_000848/B001",
          "role": "Active prevention supplies the effect that can be reproduced by the diverted people themselves."
        },
        {
          "occurrence_id": "29:38/r08",
          "branch_key": "root_000672/B001",
          "role": "The traversable road supplies the shared object of both inward diversion and outward obstruction."
        },
        {
          "occurrence_id": "29:29/r03",
          "branch_key": "root_001240/B023",
          "role": "Predatory road-blocking supplies an explicit human action that materially realizes exclusion from a route."
        },
        {
          "occurrence_id": "29:29/r04",
          "branch_key": "root_000672/B001",
          "role": "The road occurrence fixes the obstruction as interference with passage rather than mere abstract disagreement."
        },
        {
          "occurrence_id": "29:29/r05",
          "branch_key": "root_001486/B001",
          "role": "A communal assembly supplies the public institution in which obstructive practice is normalized."
        },
        {
          "occurrence_id": "29:29/r06",
          "branch_key": "root_001550/B006",
          "role": "An openly reprehensible act supplies the social content enacted within that institution."
        }
      ],
      "structural_cues": [
        "29:29 lists path-cutting among a community's own acts and locates another wrong in its public assembly.",
        "The focus orders beautified deeds before the resulting obstruction."
      ],
      "reader_inference": "Packet: one exemplum contains human road-blocking, while the focus links people's deeds to satanic diversion. Inference: diverted agents become downstream blockers who reproduce the mechanism. Alternative: the cases concern different peoples, and the focus may intend only direct diversion by Satan.",
      "changed_reading": {
        "before": "The people are passive victims of an external blocker.",
        "after": "Their beautified practices can make them active nodes of the blockage: the diverted become dividers of the route."
      }
    },
    {
      "model_id": "D05_frozen_site_archive",
      "status": "strengthened",
      "confidence": "strong",
      "mechanism": "Successive accounts show how destruction becomes legible in place: a sign is deliberately left, violent motion ends in bodies or inhabitants clinging motionless to the ground within their home, and the next ayah says clarity comes from dwellings. The site is a frozen causal archive rather than neutral scenery.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r02",
          "branch_key": "root_000170/B004",
          "role": "Disclosure into clarity supplies the interpretive output drawn from the preserved site."
        },
        {
          "occurrence_id": "29:38/r03",
          "branch_key": "root_000726/B002",
          "role": "The inhabited dwelling supplies the spatial container in which the outcome remains legible."
        },
        {
          "occurrence_id": "29:35/r01",
          "branch_key": "root_000180/B002",
          "role": "An effect remaining after departure supplies explicit preservation of evidence."
        },
        {
          "occurrence_id": "29:35/r02",
          "branch_key": "root_000074/B003",
          "role": "A conspicuous mark supplies the site's status as something meant to be read."
        },
        {
          "occurrence_id": "29:35/r03",
          "branch_key": "root_000170/B004",
          "role": "Manifest clarity supplies the stated quality of the retained sign."
        },
        {
          "occurrence_id": "29:35/r05",
          "branch_key": "root_001036/B001",
          "role": "Reason as a restraint against folly supplies the readerly operation that binds trace to warning."
        },
        {
          "occurrence_id": "29:37/r03",
          "branch_key": "root_000545/B001",
          "role": "Severe shaking supplies the destructive movement whose cessation leaves the record."
        },
        {
          "occurrence_id": "29:37/r06",
          "branch_key": "root_000222/B001",
          "role": "Being pressed to the earth and fixed in place supplies the arrest that makes catastrophe spatially legible."
        }
      ],
      "structural_cues": [
        "29:35 closes one account with an explicitly retained clear sign.",
        "29:37 closes the next with inhabitants fixed in their home, immediately before clarity from dwellings in 29:38."
      ],
      "reader_inference": "Packet: separate exempla supply a retained sign, shaking, ground-fixed inhabitants, and disclosure from dwellings. Inference: catastrophic arrest and persistence make settlement a forensic record. Alternative: the retained sign may be unspecified, and the adjacent episodes need not describe one preservation process.",
      "changed_reading": {
        "before": "The audience merely receives information about prior peoples.",
        "after": "The audience reads a material sequence preserved in place: motion, arrest, absence, and dwelling jointly expose the causal history."
      }
    },
    {
      "model_id": "D06_knowledge_orientation_split",
      "status": "strengthened",
      "confidence": "strong",
      "mechanism": "Clear proofs can be followed by arrogance; consequence attaches to one's own sin; signs can reside in the chest yet be knowingly refused; and correct cosmological answers can coexist with directional inversion and failed restraint. These repetitions sharpen مُسْتَبْصِرِينَ into an agency paradox: cognition survives, but beautified self-regard captures the layer that turns cognition into movement.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r10",
          "branch_key": "root_000121/B002",
          "role": "Inwardly penetrating awareness supplies cognition that remains present during deviation."
        },
        {
          "occurrence_id": "29:38/r04",
          "branch_key": "root_000660/B002",
          "role": "Manufactured attractiveness supplies the competing valuation that prevents cognition from governing action."
        },
        {
          "occurrence_id": "29:39/r02",
          "branch_key": "root_000170/B004",
          "role": "Uncovered evidence supplies a case where informational clarity precedes rather than prevents refusal."
        },
        {
          "occurrence_id": "29:39/r03",
          "branch_key": "root_001281/B006",
          "role": "Self-magnifying pride supplies the motive that converts received proof into self-authorizing resistance."
        },
        {
          "occurrence_id": "29:40/r03",
          "branch_key": "root_000521/B001",
          "role": "Personal wrongdoing supplies the liability attaching consequence to the agent's own conduct."
        },
        {
          "occurrence_id": "29:40/r13",
          "branch_key": "root_001533/B012",
          "role": "The person's own self supplies the reflexive location of the harm, preserving human agency within satanic diversion."
        },
        {
          "occurrence_id": "29:49/r03",
          "branch_key": "root_000849/B004",
          "role": "The inward source from which actions issue supplies a bridge between stored signs and behavioral output."
        },
        {
          "occurrence_id": "29:49/r06",
          "branch_key": "root_000224/B001",
          "role": "Refusal despite recognition supplies explicit evidence that possession of knowledge need not yield assent."
        },
        {
          "occurrence_id": "29:61/r11",
          "branch_key": "root_000041/B001",
          "role": "Turning something away from its proper face supplies directional inversion after a correct verbal answer."
        },
        {
          "occurrence_id": "29:63/r13",
          "branch_key": "root_001036/B001",
          "role": "Reason as a check on folly supplies the missing governance that factual acknowledgment alone does not provide."
        }
      ],
      "structural_cues": [
        "29:39 places clear proofs immediately before arrogance and failed escape.",
        "29:40 attributes each outcome to the agent's sin and ends with self-directed wrong.",
        "29:49 locates clear signs inwardly yet names knowing refusal.",
        "29:61 and 29:63 elicit correct answers but conclude with inversion or failure to reason."
      ],
      "reader_inference": "Packet: clarity, pride, personal liability, inward signs, recognized denial, correct answers, inversion, and failed rational restraint. Inference: the information layer is severed from the action-orienting layer, which beautification captures. Alternatives: مُسْتَبْصِرِينَ may denote worldly acumen rather than moral knowledge, and the later groups are analogues rather than the same agents.",
      "changed_reading": {
        "before": "Their insight is either rhetorical or somehow erased before they leave the path.",
        "after": "Insight can remain fully available while pride and attractive practice prevent it from controlling orientation, leaving the agents culpably self-involved."
      }
    },
    {
      "model_id": "D07_webbed_security_architecture",
      "status": "new",
      "confidence": "medium",
      "mechanism": "The immediate parable repeats deliberate taking: people take protectors and a spider takes a house. This activates the focus's beautified deeds as a constructed protection system—coherent enough to inhabit, yet unable to bear the load assigned to it. The visible ruins become the failure report of attractive but structurally weak security.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r03",
          "branch_key": "root_000726/B002",
          "role": "The inhabited dwelling supplies the focus-side architecture whose durability is placed in question."
        },
        {
          "occurrence_id": "29:38/r04",
          "branch_key": "root_000660/B002",
          "role": "Displayed attractiveness supplies the feature that can conceal structural weakness."
        },
        {
          "occurrence_id": "29:38/r06",
          "branch_key": "root_001046/B001",
          "role": "Purposive deeds supply the components through which a community constructs its practical security."
        },
        {
          "occurrence_id": "29:41/r02",
          "branch_key": "root_000018/B010",
          "role": "Deliberate acquisition supplies the shared operation by which people select patrons and the spider establishes a house."
        },
        {
          "occurrence_id": "29:41/r05",
          "branch_key": "root_001684/B004",
          "role": "Expected nearness and support supply the load-bearing function assigned to the selected protectors."
        },
        {
          "occurrence_id": "29:41/r06",
          "branch_key": "root_001054/B001",
          "role": "The weaving creature supplies a constructed network whose organization does not guarantee protective strength."
        },
        {
          "occurrence_id": "29:41/r07",
          "branch_key": "root_000166/B001",
          "role": "A house as refuge supplies the concrete security claim being tested."
        },
        {
          "occurrence_id": "29:41/r08",
          "branch_key": "root_001687/B001",
          "role": "Loss of strength supplies the hidden structural defect beneath the shelter's apparent coherence."
